{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Follow- up endoscopy rates as an indicator of effectiveness in colon capsule endoscopy: a systematic review and meta- analysis",
      "reason": "The title explicitly identifies the report as a systematic review (and meta-analysis)."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Follow- up endoscopy rates as an indicator of effectiveness in colon capsule endoscopy",
      "reason": "The title conveys the main objective: follow-up endoscopy rates as an effectiveness indicator in colon capsule endoscopy, indicating the exposure/population context."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "a systematic review and meta- analysis",
      "reason": "The title provides supplementary information on the analysis method (meta-analysis)."
    }
  ],
  "confidence": 95
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Colon capsule endoscopy (CCE) has emerged as a promising alternative for investigating lower gastrointestinal symptoms. However, its adoption has been limited due to concerns about cost-­ effectiveness, significantly influenced by follow-­ up endoscopy rates (FERs). Understanding CCE's FERs is crucial for its integration into routine clinical practice.",
      "reason": "The abstract describes the current state of knowledge (CCE as a promising alternative) and the key uncertainty (limited adoption due to cost-effectiveness concerns tied to FERs)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Understanding CCE's FERs is crucial for its integration into routine clinical practice. We synthesised the evidence to evaluate the overall rate of further investigation in CCE.",
      "reason": "The need for the review is explicitly explained: understanding FERs is crucial for clinical integration, motivating the synthesis of evidence."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": "text_11",
      "quote": "A Chinese systematic review was identified during the abstract screening stage; however, none of its referenced studies met the inclusion criteria and were therefore excluded.",
      "reason": "A previous systematic review is mentioned only in the Results as part of screening; the Introduction/rationale does not cite or discuss prior similar reviews to justify the need for the current review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of follow-up endoscopy rates after a diagnostic procedure (CCE), not a review of intervention effects, so a mechanism-of-action description is not required."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is not a review of complex interventions requiring a logic model; it examines follow-up investigation rates after a diagnostic test."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "This systematic review and meta-­ analysis aim to evaluate FERs and identify factors influencing these rates to support the effective implementation of CCE.",
      "reason": "The Introduction explicitly states the review's aims, and the Methods restate primary and secondary aims ('The primary aim of the review was to evaluate the FER following CCE. The secondary aims include exploring contributing factors to the FER')."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_4",
      "quote": "The primary aim of the review was to evaluate the FER following CCE.",
      "reason": "This is a review estimating a rate (follow-up endoscopy rate) and exploring contributing factors, not a review of comparative intervention effects; no planned PICO-style comparisons are required."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The search included full-­text clinical, retrospective, and prospective trials evaluating the use of CCE in patients with any colonic pathology... Both adult and paediatric studies were considered, provided they offered clear documentation of follow-­up investigations after the initial CCE.",
      "reason": "Eligible designs, populations (adult/paediatric), settings/indications, and follow-up documentation requirements are specified, supplemented by full-text criteria in text_7 (e.g., >10 participants, follow-up investigations prompted by incomplete procedures)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "There were no language restrictions, and all the non-­English articles were screened with the intention of being translated and included if they met the predefined inclusion criteria. However, conference abstracts were excluded due to their high risk of bias.",
      "reason": "Language (no restrictions), publication status (conference abstracts, reviews, editorials, protocols, case reports excluded; grey literature excluded per text_6), and date range (2004–2024, text_6) are all reported."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "Excluded: Underwent both colonoscopy and CCE: 29; Systematic Review paper: 5; Lack of data for synthesis: 5; Upper GI pathologies: 2; Study protocol: 2; Lack of subsequent colonoscopy: 3",
      "reason": "The PRISMA flowchart (figure_6, text_8) distinguishes 'lack of subsequent colonoscopy' (outcome not measured) from 'lack of data for synthesis' (results not extractable), but this distinction is not explained in the text."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "meta-­regression was performed, analysing prespecified subgroups or covariates, including capsule type, different CCE indications, age, sex, and the proportion of participants with adequate bowel cleansing (%) and complete transit rates (%).",
      "reason": "Synthesis groups (subgroups/covariates) are prespecified and linked to the review's secondary aim of exploring contributing factors to FER (text_4)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "conference abstracts were excluded due to their high risk of bias.",
      "reason": "Rationales are given for notable restrictions: conference abstracts (high risk of bias), upper GI follow-up exclusions (not identifiable on colonoscopy, text_7), and the 2004 search start (CCE unavailable before 2004, text_6)."
    }
  ],
  "confidence": 90
}

